import React from 'react';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  LinearProgress,
  Stack,
  Typography,
} from '@mui/material';
import {
  AutoFixHigh as AutopilotIcon,
  ExpandMore as ExpandMoreIcon,
  PlayArrow as PlayArrowIcon,
  TrendingUp as TrendingUpIcon,
} from '@mui/icons-material';
import {
  READINESS_CHECK_PRIMARY_LABEL,
  READINESS_CHECK_PRIMARY_SUBTITLE,
  READINESS_ACTION_LABELS,
  buildStageOutcomeBullets,
  humanizeOrchestrationStage,
} from '../../constants/orchestrationUxLabels';
import useReadinessLocale from '../../hooks/useReadinessLocale';
import useComplianceOrchestration from '../../hooks/useComplianceOrchestration';
import OrchestrationRunPanel, { type OrchestrationRunSummary } from './OrchestrationRunPanel';
import ComplianceOrchestrationOnboardingTip from './ComplianceOrchestrationOnboardingTip';

type ComplianceOrchestrationHubProps = {
  period?: string;
  exportApplicable?: boolean;
  overallScore?: number | null;
  indiaScore?: number | null;
  exportScore?: number | null;
  onComplete?: () => void;
  variant?: 'primary' | 'compact';
  lastRun?: OrchestrationRunSummary | null;
  showExpertDetails?: boolean;
  showOnboardingTip?: boolean;
  /** Disclosure page already shows the same label on the button. */
  hideRepeatedHeading?: boolean;
  /** A score banner on the same page already shows overall, India, and export. */
  hideScoreSummary?: boolean;
};

const scoreColor = (score: number | null | undefined): 'success' | 'warning' | 'error' | 'primary' => {
  if (score == null) return 'primary';
  if (score >= 75) return 'success';
  if (score >= 50) return 'warning';
  return 'error';
};

const ComplianceOrchestrationHub: React.FC<ComplianceOrchestrationHubProps> = ({
  period = 'annual',
  exportApplicable = false,
  overallScore = null,
  indiaScore = null,
  exportScore = null,
  onComplete,
  variant = 'primary',
  lastRun = null,
  showExpertDetails = false,
  showOnboardingTip = true,
  hideRepeatedHeading = false,
  hideScoreSummary = false,
}) => {
  const { strings } = useReadinessLocale();
  const orchestration = useComplianceOrchestration({
    period,
    exportApplicable,
    onComplete,
  });

  const displayScore = orchestration.lastResult?.overallReadinessScore ?? overallScore;
  const displayIndia = orchestration.lastResult?.indiaOverallReadinessScore ?? indiaScore;
  const displayExport = orchestration.lastResult?.exportOverallReadinessScore ?? exportScore;
  const stages = orchestration.stages.length ? orchestration.stages : lastRun?.stages || [];
  const outcomeBullets = buildStageOutcomeBullets(stages);
  const isCompact = variant === 'compact';

  return (
    <Card
      variant="outlined"
      sx={{
        mb: 3,
        borderColor: 'primary.light',
        background: isCompact
          ? 'background.paper'
          : (theme) => `linear-gradient(135deg, ${theme.palette.primary.main}08 0%, ${theme.palette.background.paper} 60%)`,
      }}
    >
      <CardContent>
        {showOnboardingTip && !isCompact ? <ComplianceOrchestrationOnboardingTip /> : null}
        {!isCompact ? (
          <Typography variant="overline" color="primary" sx={{ letterSpacing: 1.2, fontWeight: 700 }}>
            One-step readiness
          </Typography>
        ) : null}
        <Stack
          direction={{ xs: 'column', md: isCompact ? 'row' : 'row' }}
          spacing={2}
          alignItems={{ xs: 'stretch', md: 'center' }}
          justifyContent="space-between"
          sx={{ mb: 2 }}
        >
          <Box sx={{ flex: 1, minWidth: 0 }}>
            {hideRepeatedHeading ? null : (
              <Typography variant={isCompact ? 'subtitle1' : 'h6'} fontWeight={700} gutterBottom>
                {strings.checkReadiness || READINESS_CHECK_PRIMARY_LABEL}
              </Typography>
            )}
            <Typography variant="body2" color="text.secondary" sx={{ maxWidth: 560 }}>
              {strings.checkReadinessSubtitle || READINESS_CHECK_PRIMARY_SUBTITLE}
            </Typography>
          </Box>
          {hideScoreSummary ? null : (
          <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap alignItems="center">
            {displayScore != null ? (
              <Chip
                icon={<TrendingUpIcon />}
                label={`${Math.round(displayScore)}% ready`}
                color={scoreColor(displayScore)}
                variant="outlined"
                sx={{ fontWeight: 600 }}
              />
            ) : null}
            {displayIndia != null ? (
              <Chip size="small" label={`India ${Math.round(displayIndia)}%`} variant="outlined" />
            ) : null}
            {exportApplicable && displayExport != null ? (
              <Chip size="small" label={`Export ${Math.round(displayExport)}%`} variant="outlined" />
            ) : null}
          </Stack>
          )}
        </Stack>

        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.5} sx={{ mb: orchestration.running ? 2 : 0 }}>
          <Button
            variant="contained"
            size={isCompact ? 'medium' : 'large'}
            disabled={orchestration.running}
            onClick={() => { void orchestration.runFullReadinessCheck(); }}
            startIcon={orchestration.running ? <CircularProgress size={20} color="inherit" /> : <PlayArrowIcon />}
          >
            {orchestration.running ? 'Checking…' : (strings.checkReadiness || READINESS_CHECK_PRIMARY_LABEL)}
          </Button>
          <Button
            variant="outlined"
            disabled={orchestration.autopilotRunning || orchestration.running}
            onClick={() => { void orchestration.runAutopilot(); }}
            startIcon={orchestration.autopilotRunning ? <CircularProgress size={18} /> : <AutopilotIcon />}
          >
            {orchestration.autopilotRunning ? 'Matching bills…' : READINESS_ACTION_LABELS.autoFixFromDocuments}
          </Button>
        </Stack>

        {orchestration.running ? (
          <Box sx={{ mt: 2 }}>
            <LinearProgress sx={{ mb: 1, height: 6, borderRadius: 1 }} />
            <Typography variant="caption" color="text.secondary">
              Scanning bills, BRSR fields, ISO boundaries, and export checks — stay on this page.
            </Typography>
          </Box>
        ) : null}

        {orchestration.feedback ? (
          <Alert severity={orchestration.hasPartialFailures ? 'warning' : 'success'} sx={{ mt: 2 }}>
            {orchestration.feedback}
          </Alert>
        ) : null}
        {orchestration.hasPartialFailures && orchestration.partialFailures.length > 0 ? (
          <Alert severity="warning" sx={{ mt: 1 }}>
            {orchestration.partialFailures.slice(0, 3).map((failure) => (
              <Typography key={failure.id || failure.message} variant="body2">
                • {failure.message || failure.id}
              </Typography>
            ))}
          </Alert>
        ) : null}
        {orchestration.error ? (
          <Alert severity="error" sx={{ mt: 2 }}>{orchestration.error}</Alert>
        ) : null}

        {!orchestration.running && outcomeBullets.length > 0 && !isCompact ? (
          <Box sx={{ mt: 2, p: 1.5, borderRadius: 1, bgcolor: 'action.hover' }}>
            <Typography variant="caption" color="text.secondary" fontWeight={600} display="block" sx={{ mb: 0.5 }}>
              What we checked
            </Typography>
            {outcomeBullets.map((bullet) => (
              <Typography key={bullet} variant="body2" color="text.secondary">
                ✓ {bullet}
              </Typography>
            ))}
          </Box>
        ) : null}

        {(showExpertDetails || stages.length > 0) && !orchestration.running ? (
          <Accordion
            disableGutters
            elevation={0}
            sx={{ bgcolor: 'transparent', '&:before': { display: 'none' }, mt: 2 }}
          >
            <AccordionSummary expandIcon={<ExpandMoreIcon />} sx={{ px: 0, minHeight: 36 }}>
              <Typography variant="body2" color="text.secondary">
                Technical step detail
              </Typography>
            </AccordionSummary>
            <AccordionDetails sx={{ px: 0, pt: 0 }}>
              {stages.length ? (
                <Stack spacing={0.5}>
                  {stages.map((stage) => (
                    <Typography key={stage.stage} variant="caption" color="text.secondary" display="block">
                      {stage.status === 'completed' ? '✓' : stage.status === 'skipped' ? '–' : '✗'}{' '}
                      {humanizeOrchestrationStage(stage.stage)}
                    </Typography>
                  ))}
                </Stack>
              ) : (
                <OrchestrationRunPanel lastRun={lastRun} compact showEmptyPrompt />
              )}
            </AccordionDetails>
          </Accordion>
        ) : null}
      </CardContent>
    </Card>
  );
};

export default ComplianceOrchestrationHub;
