export const msmeShareStatusLabel = (level?: string | null, score?: number | null): string => {
  const numericScore = Math.round(Number(score) || 0);
  if (level === 'filing_ready') return numericScore > 0 ? `Ready to file (${numericScore}%)` : 'Ready to file';
  if (level === 'readiness_assessment') {
    if (numericScore >= 85) return `Strong progress (${numericScore}%)`;
    if (numericScore >= 70) return `In progress (${numericScore}%)`;
    return numericScore > 0 ? `Building readiness (${numericScore}%)` : 'Building readiness';
  }
  if (numericScore >= 50) return `Draft shareable (${numericScore}%)`;
  return numericScore > 0 ? `Early draft (${numericScore}%)` : 'Ready to share (PDF)';
};

export const msmeReadinessScoreBand = (score?: number | null): 'early' | 'building' | 'almost' | 'ready' => {
  const value = Math.round(Number(score) || 0);
  if (value >= 90) return 'ready';
  if (value >= 75) return 'almost';
  if (value >= 50) return 'building';
  return 'early';
};

export const msmeTabLoadStatusLabel = (loaded: boolean, filingReady: boolean, score?: number | null): string => {
  if (filingReady) return 'Filing ready';
  if (score != null && Number.isFinite(Number(score))) {
    const pct = Math.round(Number(score) || 0);
    const band = msmeReadinessScoreBand(score);
    if (!loaded) {
      if (band === 'ready' || band === 'almost') return `${pct}% — almost there`;
      return `${pct}% — in progress`;
    }
    if (band === 'ready' || band === 'almost') return `Loaded · ${pct}% — almost there`;
    return `Loaded · ${pct}% — in progress`;
  }
  if (!loaded) return 'Loading…';
  return 'Loading readiness…';
};

export const msmePdfDownloadLabel = (
  tabValue: number,
  readinessLevel?: string | null
): string => {
  const filingReady = readinessLevel === 'filing_ready';
  if (tabValue === REPORTING_TAB.CBAM) {
    return filingReady ? 'Download CBAM report (PDF)' : 'Download CBAM summary to share';
  }
  if (tabValue === REPORTING_TAB.ISO_14064) {
    return filingReady ? 'Download ISO inventory (PDF)' : 'Download inventory summary to share';
  }
  if (tabValue === REPORTING_TAB.ISO_14067) {
    return filingReady ? 'Download product footprint (PDF)' : 'Download product report to share';
  }
  return filingReady ? 'Download BRSR pack (PDF)' : 'Download report to share with buyer';
};

