export const remediationLinkForBlockedReason = (reason: string): string | null => {
  const text = reason.toLowerCase();
  if (/gps|geotag|site photo|installation boundary/.test(text)) {
    return '/compliance/geotagged-capture';
  }
  if (/supplier registry|precursor vendor|upstream supplier/.test(text)) {
    return '/compliance/export?section=supplier-portal';
  }
  if (/upload|bill|document|ocr|utility|electricity|fuel|meter|kwh|litre|liter|kg/.test(text)) {
    return DOCUMENT_UPLOAD_PATH;
  }
  if (/scope\s*3|residual|category-level|explicitly measured/.test(text)) {
    return DOCUMENT_UPLOAD_PATH;
  }
  if (/tier\s*1|spend-proxy|spend proxy|activity-based|activity data|zoho|tally|accounting/.test(text)) {
    return '/compliance/india?section=data-sync';
  }
  if (/lci granularity|product-level lci|stage-level activity|allocation key|factor reference/.test(text)) {
    return DOCUMENT_UPLOAD_PATH;
  }
  if (/product cfp|functional unit|allocation method|lifecycle stage|iso 14067|system boundary|boundary rigor/.test(text)) {
    return '/compliance/product-pcf';
  }
  if (/product signal|product identifier|manufacturing workflow|primary product|product catalog/.test(text)) {
    return '/msme-profile';
  }
  if (/base year|recalculation|methodology|inventory owner|governance|boundary|assurance check|close gap|uncertainty|consolidation|facilities|factor registry|verification metadata|accountable inventory/.test(text)) {
    return '/compliance/india?section=iso-assurance';
  }
  if (/assessment|baseline|footprint|questionnaire/.test(text)) {
    return '/carbon-footprint?section=start-assessment';
  }
  if (/cbam|export|installation|registry|shipment|tier 1 data|embedded emission/.test(text)) {
    return '/compliance/export?section=cbam';
  }
  if (/buyer|supplier|questionnaire|template/.test(text)) {
    return '/compliance';
  }
  if (/boundary|operations|manufacturing|product|principle 6|section a|section c|intensity/.test(text)) {
    return '/compliance/india?section=brsr-core';
  }
  if (/mitigation|reduction measure|abatement|selected action/.test(text)) {
    return '/carbon-footprint?section=recommendations';
  }
  return '/compliance';
};

export const remediationActionLabelForBlockedReason = (reason: string): string => {
  const link = remediationLinkForBlockedReason(reason);
  if (link === DOCUMENT_UPLOAD_PATH) return 'Upload bills';
  if (link?.includes('data-sync')) return 'Improve bill & accounting data';
  if (link?.includes('iso-assurance')) return 'Finish inventory checks';
  if (link?.includes('product-pcf')) return 'Open product footprint';
  if (link?.includes('msme-profile')) return 'Update company profile';
  if (link?.includes('brsr-core')) return 'Complete buyer pack fields';
  if (link?.includes('epr-compliance')) return 'Open waste take-back';
  if (link?.includes('overview') || link?.includes('start-assessment')) return 'Run assessment';
  if (link?.includes('supplier-portal')) return 'Map suppliers';
  if (link?.includes('geotagged-capture')) return 'Capture site photos / GPS';
  if (link?.includes('compliance/export')) return 'Open EU export setup';
  if (link?.includes('/documents')) return 'Add category data';
  return 'Fix this step';
};

