export const remediationWarningTypeForBlockedReason = (reason: string): string => {
  const text = reason.toLowerCase();
  if (/ocr|unreadable|confidence/.test(text)) return 'ocr_low_confidence';
  if (/spend-proxy|spend proxy|₹-based|tier 2/.test(text)) return 'spend_proxy_heavy';
  if (/scope\s*3|residual/.test(text)) return 'readiness_blocked';
  if (/assurance gate|assurance check/.test(text)) return 'assurance_gate_blocked';
  if (/data quality|tier 1/.test(text)) return 'inventory_quality_low';
  if (/verify|verification pending/.test(text)) return 'document_verification_pending';
  return 'filing_export_blocked';
};

export const estimatedScoreImpactForRemediation = (reason: string): number | null => {
  const text = reason.toLowerCase();
  if (/tier\s*1|spend-proxy|meter|kwh|activity/.test(text)) return 12;
  if (/scope\s*3|residual|category/.test(text)) return 10;
  if (/completeness|mandatory field|section a|section c|principle 6/.test(text)) return 15;
  if (/iso|assurance|boundary|base year|methodology/.test(text)) return 12;
  if (/cbam|installation|shipment|documentation/.test(text)) return 10;
  return null;
};

export const readinessRank = (level?: string | null): number => {
  const ranks: Record<ReportReadinessLevel, number> = {
    prep_draft: 0,
    readiness_assessment: 1,
    filing_ready: 2,
  };
  return ranks[(level as ReportReadinessLevel) || 'prep_draft'] ?? 0;
};

export const msmeProgressLabel = (score?: number | null): string => {
  const value = Math.round(Number(score) || 0);
  if (value >= 85) return `${value}% — you can unlock official files soon`;
  if (value >= 75) return `${value}% — a few steps left`;
  if (value >= 50) return `${value}% — upload bills to improve`;
  return `${value}% — start with assessment and 1–2 bills`;
};

export type ReadinessChipColor = 'default' | 'success' | 'warning' | 'info' | 'error';

/** MUI chip color from readiness level plus optional score band (Phase 4 UX). */
export const readinessLevelChipColor = (
  level?: string | null,
  score?: number | null
): ReadinessChipColor => {
  if (level === 'filing_ready') return 'success';
  if (level === 'readiness_assessment') {
    const band = msmeReadinessScoreBand(score);
    return band === 'early' ? 'warning' : 'info';
  }
  const band = msmeReadinessScoreBand(score);
  if (band === 'ready' || band === 'almost') return 'info';
  if (band === 'building') return 'warning';
  return 'default';
};

/** Human-readable chip label — prefers framework label, else score-band share status. */
export const readinessLevelChipLabel = (
  level?: string | null,
  score?: number | null,
  frameworkLabel?: string | null
): string => {
  if (frameworkLabel) return frameworkLabel;
  return msmeShareStatusLabel(level, score);
};

export const msmeReadinessScoreBandLabel = (score?: number | null): string => {
  const band = msmeReadinessScoreBand(score);
  const value = Math.round(Number(score) || 0);
  switch (band) {
    case 'ready':
      return value > 0 ? `Ready band (${value}%)` : 'Ready band';
    case 'almost':
      return value > 0 ? `Almost ready (${value}%)` : 'Almost ready';
    case 'building':
      return value > 0 ? `Building (${value}%)` : 'Building readiness';
    default:
      return value > 0 ? `Early draft (${value}%)` : 'Early draft';
  }
};
